/**
 * USGS Data Series 140, Historical Statistics for Mineral and Material Commodities in the United States: the 121
 * commodity sheets the store holds as one table each (a record per year, the workbook's header row as the dictionary).
 * Generated on 26 Nov 2026 from production (dictionary, rows, snapshot of each table) and the 92 workbooks USGS
 * publishes, read one at a time: each table's labels equal its sheet's header row in order and its records equal the
 * sheet's year rows in number; 32 tables were compared cell for cell (all equal, industry.checks.json).
 *
 * A measure's unit is the sheet's own: the statement above its header ("[All values in metric tons (t) gross
 * weight unless otherwise noted]") for a quantity, or the unit the header itself states: "$/t" (the value of one
 * metric ton in current dollars), "98$/t" (the same in constant 1998 U.S. dollars, by the Consumer Price Index), "(%)",
 * "($)", or a basis in brackets ("World production (gross weight)" in a sheet stated in content). A column whose unit
 * no statement covers ("Employment" in the aluminum sheet) is not a measure. The two titanium mineral sheets have a
 * two-row header that the store joined ("Imports | Ilmenite"); they are not listed.
 */
export type Ds140Measure = readonly [field: string, unit: string, label?: string];

export type Ds140Table = {
  /** The dataset id after "official_07_materials_csv_". */
  id: string;
  /** The snapshot whose dictionary and rows were checked. */
  snapshotId: string;
  /** Records of that snapshot: one per year. */
  rows: number;
  /** The workbook, after "https://d9-wret.s3.us-west-2.amazonaws.com/assets/palladium/production/". */
  workbook: string;
  /** The sheet's unit statement, verbatim. */
  statement: string;
  /** The unit the statement gives a quantity ("metric tons (t) copper content"). */
  unit: string;
  /**
   * Measures in sheet order: the field label as stored, the unit ("s" the statement's, "$" for $/t, "98" for 98$/t,
   * "%" for Percent, "usd" for $, or a unit text), and the label a reader sees when it differs from the field.
   */
  measures: readonly Ds140Measure[];
};

